create table if not exists public.categories (id bigint generated by default as identity primary key, slug text unique not null, name text not null, description text, created_at timestamptz not null default now());
create table if not exists public.articles (id bigint generated by default as identity primary key, slug text unique not null, title text not null, dek text, body jsonb not null default '[]'::jsonb, hero_text text, hero_image text, category_id bigint references public.categories(id) on delete set null, status text not null default 'draft' check (status in ('draft','published','archived')), published_at timestamptz, reading_minutes integer, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.tags (id bigint generated by default as identity primary key, slug text unique not null, name text not null);
create table if not exists public.article_tags (article_id bigint not null references public.articles(id) on delete cascade, tag_id bigint not null references public.tags(id) on delete cascade, primary key(article_id,tag_id));
create table if not exists public.newsletter_subscribers (id bigint generated by default as identity primary key, email text unique not null, created_at timestamptz not null default now());
alter table public.categories enable row level security; alter table public.articles enable row level security; alter table public.tags enable row level security; alter table public.article_tags enable row level security; alter table public.newsletter_subscribers enable row level security;
create policy "published articles are public" on public.articles for select to anon,authenticated using (status='published');
create policy "categories are public" on public.categories for select to anon,authenticated using (true);
create policy "tags are public" on public.tags for select to anon,authenticated using (true);
create policy "article tags are public" on public.article_tags for select to anon,authenticated using (true);
create policy "subscribe" on public.newsletter_subscribers for insert to anon,authenticated with check (true);
grant select on public.articles,public.categories,public.tags,public.article_tags to anon,authenticated; grant insert on public.newsletter_subscribers to anon,authenticated;
insert into public.categories(slug,name) values ('systems','Systems'),('economics','Economics'),('culture','Culture'),('science','Science'),('infrastructure','Infrastructure'),('what-if','What If?') on conflict (slug) do nothing;